package main

import "fmt"

// Request 模型：真实 net/http 的 *http.Request 也装着方法、路径、查询这些信息。
type Request struct {
	Method string
	Query  map[string]string
}
// Response 模型：状态码 + 响应体，对应 ResponseWriter 要写回客户端的内容。
type Response struct{ Status int; Body string }

// Handle 是纯函数：同样的请求必得同样的响应，没有隐藏状态，也好测试。
func Handle(req Request) Response {
	if req.Method != "GET" {
		return Response{Status: 405, Body: "方法不允许"}
	}
	if name := req.Query["name"]; name != "" {
		return Response{Status: 200, Body: "你好，" + name}
	}
	return Response{Status: 200, Body: "你好，访客"}
}

func main() {
	for _, req := range []Request{
		{Method: "GET", Query: map[string]string{"name": "Go"}},
		{Method: "GET"},
		{Method: "POST"},
	} {
		resp := Handle(req)
		fmt.Println(req.Method, "->", resp.Status, resp.Body)
	}
}

