package main

import (
	"fmt"
	"strings"
)

// Handler 是简化版 ServeHTTP：入参路径，返回响应体。
type Handler func(path string) string

// Log 中间件接收 Handler 并返回新的 Handler，在业务前后插入逻辑。
func Log(next Handler) Handler {
	return func(path string) string {
		fmt.Println("->", path)
		body := next(path)
		fmt.Println("<-", body)
		return body
	}
}

// Auth 只放行 /home，其余路径直接 403，不进入业务 Handler。
func Auth(next Handler) Handler {
	return func(path string) string {
		if !strings.HasPrefix(path, "/home") {
			return "403 无权限"
		}
		return next(path)
	}
}

func main() {
	handler := Log(Auth(func(path string) string { return "200 首页" }))
	fmt.Println("结果:", handler("/admin"))
	fmt.Println("结果:", handler("/home"))
}

