package main

import (
	"fmt"
	"strings"
)

// Router 是“路径 → 响应”的映射表；键以斜杠结尾表示前缀规则，其余是精确匹配。
type Router map[string]string

// Lookup 先精确匹配，再选最长的前缀规则：ServeMux 也是长前缀优先。
func (r Router) Lookup(path string) string {
	if body, ok := r[path]; ok {
		return body
	}
	best, body := "", ""
	for rule, b := range r {
		if len(rule) > 1 && strings.HasSuffix(rule, "/") &&
			strings.HasPrefix(path, rule) && len(rule) > len(best) {
			best, body = rule, b
		}
	}
	if best == "" {
		return "404 未找到"
	}
	return body
}

func main() {
	router := Router{"/": "首页", "/static/": "静态资源", "/users/": "用户详情"}
	for _, path := range []string{"/", "/users/42", "/static/app.css", "/nope"} {
		fmt.Println(path, "->", router.Lookup(path))
	}
}

