package main

import (
	"fmt"
	"strconv"
	"strings"
)

// Validate 校验 page 参数：空值给默认值，非法值返回可定位的 400 文案。
func Validate(raw string) string {
	text := strings.TrimSpace(raw)
	if text == "" {
		return "200 page=1"
	}
	page, err := strconv.Atoi(text)
	if err != nil {
		return "400 page 需要整数，收到 " + text
	}
	if page < 1 {
		return "400 page 需要大于 0，收到 " + text
	}
	return "200 page=" + strconv.Itoa(page)
}

func main() {
	for _, raw := range []string{"2", "", "abc", "0"} {
		fmt.Println(Validate(raw))
	}
}

