package main

import "fmt"

// handle 在独立 goroutine 里模拟一次下游调用：cost 是耗时步数，budget 是超时预算。
// 真实场景这里会是带 context 超时的 http.Client，练习里用可运行的模型代替。
func handle(cost, budget int, done chan bool) chan string {
	out := make(chan string, 1)
	go func() {
		if cost <= budget {
			out <- "成功"
		}
		done <- true // 成败都要通知主协程，避免“没跑完就判超时”
	}()
	return out
}

// collect 用 select 加 default 非阻塞取值：拿不到结果即超时，走降级。
func collect(out chan string) string {
	select {
	case data := <-out:
		return data
	default:
		return "降级：返回缓存"
	}
}

func main() {
	done := make(chan bool, 2)
	fast, slow := handle(1, 3, done), handle(9, 3, done)
	<-done
	<-done
	fmt.Println("请求A:", collect(fast))
	fmt.Println("请求B:", collect(slow))
}

